//
// js-runtimes — one package.json, every JavaScript runtime
// (3-practice/LANGUAGE-POLICY.adoc §1.4). Preference order: Bun, Deno, pnpm,
// npm.
//
//   js-runtimes regen [DIR]           the only writer: package.json to JCS, then
//                                     bun.lock, deno.lock and pnpm-lock.yaml,
//                                     each regenerated by its own tool
//   js-runtimes check RUNTIME [DIR]   the gate, for bun|deno|pnpm: JCS, lock
//                                     present, FROZEN install (a stale lock
//                                     fails), `test` script under RUNTIME
//   js-runtimes pick [DIR]            print the most-preferred runtime on PATH
//   js-runtimes run SCRIPT [DIR]      run a package.json script with it
//   js-runtimes provision [DIR]       every environment definition (mise,
//                                     Containerfile, Guix) provisions Bun, or
//                                     the best runtime it can
//
// Exit: 0 pass; 1 a finding; 2 cannot run (missing tool, manifest or
// argument). A gate that cannot look does not report a pass.

use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode, Stdio};

use js_runtimes::{
    canon, find_env_defs, has_test_script, pick, verdict, Canon, Runtime, Verdict, LOCKED, ORDER,
};

const USAGE: &str = "usage: js-runtimes regen [DIR] | check bun|deno|pnpm [DIR] | pick [DIR] | run SCRIPT [DIR] | provision [DIR]";

struct Fail(u8, String);

/// An exit-code-1 failure: a finding was reported.
fn finding(msg: impl Into<String>) -> Fail {
    Fail(1, msg.into())
}
/// An exit-code-2 failure: the check could not run at all.
fn cannot(msg: impl Into<String>) -> Fail {
    Fail(2, msg.into())
}
/// Prints an informational line prefixed with the tool's name.
fn note(msg: &str) {
    println!("js-runtimes: {msg}");
}

/// Whether `bin` is on `PATH` and executable.
fn on_path(bin: &str) -> bool {
    let Some(paths) = env::var_os("PATH") else {
        return false;
    };
    env::split_paths(&paths).any(|d| {
        let p = d.join(bin);
        p.is_file() && fs::metadata(&p).map(|m| is_executable(&m)).unwrap_or(false)
    })
}

/// Whether the Unix permission bits mark this file executable.
#[cfg(unix)]
fn is_executable(m: &fs::Metadata) -> bool {
    use std::os::unix::fs::PermissionsExt;
    m.permissions().mode() & 0o111 != 0
}
/// Non-Unix platforms have no executable bit to check.
#[cfg(not(unix))]
fn is_executable(_: &fs::Metadata) -> bool {
    true
}

/// Requires `bin` to be on `PATH`, else a cannot-run failure.
fn need(bin: &str) -> Result<(), Fail> {
    if on_path(bin) {
        Ok(())
    } else {
        Err(cannot(format!(
            "{bin} is not on PATH (cannot run, not a pass)"
        )))
    }
}

/// Run quietly; on failure, show what the tool said before the verdict.
fn quiet(dir: &Path, argv: &[&str]) -> Result<bool, Fail> {
    let out = Command::new(argv[0])
        .args(&argv[1..])
        .current_dir(dir)
        .stdin(Stdio::null())
        .output()
        .map_err(|e| cannot(format!("could not start {}: {e}", argv[0])))?;
    if !out.status.success() {
        eprint!("{}", String::from_utf8_lossy(&out.stdout));
        eprint!("{}", String::from_utf8_lossy(&out.stderr));
    }
    Ok(out.status.success())
}

/// Run with inherited stdout/stderr, e.g. for the `test` script.
fn loud(dir: &Path, argv: &[&str]) -> Result<bool, Fail> {
    let st = Command::new(argv[0])
        .args(&argv[1..])
        .current_dir(dir)
        .stdin(Stdio::null())
        .status()
        .map_err(|e| cannot(format!("could not start {}: {e}", argv[0])))?;
    Ok(st.success())
}

/// Reads `package.json` from `dir`, or a cannot-run failure.
fn manifest(dir: &Path) -> Result<(PathBuf, Vec<u8>), Fail> {
    let p = dir.join("package.json");
    match fs::read(&p) {
        Ok(b) => Ok((p, b)),
        Err(_) => Err(cannot(format!("no package.json in {}", dir.display()))),
    }
}

/// Rewrites `path` to its canonical JCS form if it is not already.
fn canonicalise(path: &Path, bytes: &[u8]) -> Result<(), Fail> {
    match canon(bytes) {
        Canon::Canonical => Ok(()),
        Canon::NotCanonical(wanted) => fs::write(path, wanted)
            .map_err(|e| cannot(format!("could not write {}: {e}", path.display()))),
        Canon::Invalid(e) => Err(finding(format!("package.json is not I-JSON: {e}"))),
    }
}

/// The only writer: canonicalises `package.json`, then regenerates each
/// runtime's lock.
fn regen(dir: &Path) -> Result<(), Fail> {
    let (path, bytes) = manifest(dir)?;
    for r in LOCKED {
        need(r.name())?;
    }
    if dir.join("bun.lockb").exists() {
        return Err(finding(
            "bun.lockb (binary) present: remove it; bun.lock is the text lock",
        ));
    }
    canonicalise(&path, &bytes)?;
    let steps: [(&str, &[&str]); 3] = [
        ("bun", &["bun", "install", "--lockfile-only"]),
        // deno has no lockfile-only mode; it also populates node_modules.
        ("deno", &["deno", "install"]),
        ("pnpm", &["pnpm", "install", "--lockfile-only"]),
    ];
    for (name, argv) in steps {
        if !quiet(dir, argv)? {
            return Err(finding(format!("{name} could not resolve package.json")));
        }
    }
    // A tool that rewrote package.json while resolving is put back in canon.
    let bytes =
        fs::read(&path).map_err(|e| cannot(format!("could not reread package.json: {e}")))?;
    canonicalise(&path, &bytes)?;
    note(&format!(
        "regenerated in {}: package.json (JCS), bun.lock, deno.lock, pnpm-lock.yaml",
        dir.display()
    ));
    Ok(())
}

/// The gate for one runtime: JCS, lock present, frozen install, then the
/// `test` script.
fn check(rt: Runtime, dir: &Path) -> Result<(), Fail> {
    let Some(lock) = rt.lockfile() else {
        return Err(cannot(format!(
            "{rt} keeps no tracked lock (package-lock.json stays refused); check one of: bun, deno, pnpm"
        )));
    };
    let (_, bytes) = manifest(dir)?;
    need(rt.name())?;
    match canon(&bytes) {
        Canon::Canonical => note("package.json is I-JSON + JCS"),
        Canon::NotCanonical(_) => {
            return Err(finding(
                "package.json is not JCS-canonical: run js-runtimes regen",
            ))
        }
        Canon::Invalid(e) => return Err(finding(format!("package.json is not I-JSON: {e}"))),
    }
    if !dir.join(lock).is_file() {
        return Err(finding(format!("{lock} is missing: run js-runtimes regen")));
    }
    let frozen: &[&str] = match rt {
        Runtime::Bun => &["bun", "install", "--frozen-lockfile"],
        Runtime::Deno => &["deno", "install", "--frozen"],
        Runtime::Pnpm => &["pnpm", "install", "--frozen-lockfile"],
        Runtime::Npm => unreachable!("npm has no lock"),
    };
    if !quiet(dir, frozen)? {
        return Err(finding(format!(
            "{rt}: {lock} is stale against package.json (frozen install refused): run js-runtimes regen"
        )));
    }
    note(&format!("{rt} installs frozen from {lock}"));
    if has_test_script(&bytes) {
        let [bin, sub] = rt.run_script();
        if !loud(dir, &[bin, sub, "test"])? {
            return Err(finding(format!("{rt}: the test script failed")));
        }
        note(&format!("{rt} ran the test script"));
    } else {
        note(&format!("{rt}: no test script (install-only check)"));
    }
    Ok(())
}

/// The most-preferred runtime on `PATH`, or a cannot-run failure.
fn picked() -> Result<Runtime, Fail> {
    pick(|r| on_path(r.name())).ok_or_else(|| {
        cannot(format!(
            "no JavaScript runtime on PATH (looked for, in order: {}); provision Bun (mise.toml `bun = \"…\"`)",
            ORDER.map(Runtime::name).join(", ")
        ))
    })
}

/// Checks that every environment definition under `dir` provisions Bun, or
/// the best runtime it can.
fn provision(dir: &Path) -> Result<(), Fail> {
    if !dir.join("package.json").is_file() {
        note("no package.json: nothing here needs a JavaScript runtime (0 environment definitions examined)");
        return Ok(());
    }
    let defs = find_env_defs(dir);
    if defs.is_empty() {
        return Err(finding(
            "package.json needs a JavaScript runtime, but no environment definition (mise.toml, Containerfile, guix.scm/manifest.scm) provisions one: add `bun = \"<version>\"` to mise.toml",
        ));
    }
    let mut bad = 0;
    let mut any_js = false;
    for d in &defs {
        let names: Vec<_> = d.provides.iter().map(|r| r.name()).collect();
        let shown = if names.is_empty() {
            "none".to_string()
        } else {
            names.join(", ")
        };
        match verdict(d) {
            Verdict::Best => {
                any_js = true;
                note(&format!(
                    "OK    {} ({}): provides {shown}; bun first",
                    d.path.display(),
                    d.kind.name()
                ));
            }
            Verdict::Fallback(r) => {
                any_js = true;
                note(&format!(
                    "OK    {} ({}): provides {shown}; best is {r} (bun is not always packaged for {}: accepted, reported)",
                    d.path.display(),
                    d.kind.name(),
                    d.kind.name()
                ));
            }
            Verdict::Below(r) => {
                any_js = true;
                bad += 1;
                eprintln!(
                    "js-runtimes: FAIL  {} ({}): best runtime provisioned is {r}, but bun can be provisioned here and comes first",
                    d.path.display(),
                    d.kind.name()
                );
            }
            Verdict::None => {
                note(&format!(
                    "--    {} ({}): provisions no JavaScript runtime",
                    d.path.display(),
                    d.kind.name()
                ));
            }
        }
    }
    if !any_js {
        bad += 1;
        eprintln!(
            "js-runtimes: FAIL  package.json needs a JavaScript runtime, and none of the {} environment definition(s) provisions one: add `bun = \"<version>\"` to mise.toml",
            defs.len()
        );
    }
    if bad > 0 {
        return Err(finding(format!(
            "{bad} provisioning finding(s) across {} environment definition(s)",
            defs.len()
        )));
    }
    note(&format!(
        "provisioning: {} environment definition(s) examined, preference order satisfied",
        defs.len()
    ));
    Ok(())
}

/// Dispatches the subcommand named by `args[0]`.
fn real_main(args: &[String]) -> Result<(), Fail> {
    let dir_at = |i: usize| PathBuf::from(args.get(i).map(String::as_str).unwrap_or("."));
    match args.first().map(String::as_str) {
        Some("regen") => regen(&dir_at(1)),
        Some("check") => {
            let rt = args.get(1).ok_or_else(|| cannot(USAGE))?;
            let rt = Runtime::parse(rt).ok_or_else(|| {
                cannot(format!(
                    "unknown runtime '{rt}' (want one of: bun deno pnpm)"
                ))
            })?;
            check(rt, &dir_at(2))
        }
        Some("pick") => {
            let _ = dir_at(1);
            println!("{}", picked()?);
            Ok(())
        }
        Some("run") => {
            let script = args.get(1).ok_or_else(|| cannot(USAGE))?;
            let dir = dir_at(2);
            manifest(&dir)?;
            let rt = picked()?;
            let [bin, sub] = rt.run_script();
            // To stderr: stdout belongs to the script.
            eprintln!(
                "js-runtimes: running `{script}` with {rt} (first available of {})",
                ORDER.map(Runtime::name).join(" > ")
            );
            if loud(&dir, &[bin, sub, script])? {
                Ok(())
            } else {
                Err(finding(format!("{rt}: script `{script}` failed")))
            }
        }
        Some("provision") => provision(&dir_at(1)),
        Some("-h") | Some("--help") => {
            println!("{USAGE}");
            Ok(())
        }
        _ => Err(cannot(USAGE)),
    }
}

/// Entry point: runs `real_main` and maps the result to an exit code.
fn main() -> ExitCode {
    let args: Vec<String> = env::args().skip(1).collect();
    match real_main(&args) {
        Ok(()) => ExitCode::SUCCESS,
        Err(Fail(code, msg)) => {
            eprintln!("js-runtimes: {msg}");
            ExitCode::from(code)
        }
    }
}
